function PriceGauge({ low, mid, high, marketAvg }) {
  const range = high - low;
  const avgPos = ((marketAvg - low) / range) * 100;
  return (
    <div style={{ padding: "24px 0" }}>
      <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 28 }}>
        <div style={{ textAlign: "left" }}>
          <div style={{ fontSize: 11, color: "#5a8a6a", fontWeight: 600 }}>偏低</div>
          <div style={{ fontSize: 22, fontWeight: 900, color: "#5a8a6a" }}>{low}</div>
        </div>
        <div style={{ textAlign: "center" }}>
          <div style={{ fontSize: 11, color: "#c0903a", fontWeight: 600 }}>AI 估算</div>
          <div style={{ fontSize: 36, fontWeight: 900, color: "#c0903a" }}>{mid}</div>
          <div style={{ fontSize: 11, color: "#b8b0a8" }}>萬/坪</div>
        </div>
        <div style={{ textAlign: "right" }}>
          <div style={{ fontSize: 11, color: "#c07050", fontWeight: 600 }}>偏高</div>
          <div style={{ fontSize: 22, fontWeight: 900, color: "#c07050" }}>{high}</div>
        </div>
      </div>
      {/* gradient bar */}
      <div style={{ position: "relative", height: 12, borderRadius: 6, background: "linear-gradient(to right, #5a8a6a, #e2c87a, #c07050)", marginBottom: 8 }}>
        {/* AI mid marker */}
        <div style={{ position: "absolute", left: "50%", top: -6, transform: "translateX(-50%)", width: 24, height: 24, borderRadius: 12, background: "#c0903a", border: "3px solid #fff", boxShadow: "0 2px 8px rgba(192,144,58,0.3)", display: "flex", alignItems: "center", justifyContent: "center" }}>
          <span style={{ fontSize: 8, color: "#fff", fontWeight: 800 }}>AI</span>
        </div>
        {/* market avg marker */}
        <div style={{ position: "absolute", left: `${Math.min(Math.max(avgPos, 5), 95)}%`, bottom: -20, transform: "translateX(-50%)", fontSize: 10, color: "#8a8278", fontWeight: 600, whiteSpace: "nowrap" }}>
          ▲ 周邊均價 {marketAvg}
        </div>
      </div>
    </div>
  );
}

function TrendChart({ data }) {
  const max = Math.max(...data.map(d => d.price));
  const min = Math.min(...data.map(d => d.price));
  const range = max - min || 1;
  return (
    <div>
      <div style={{ display: "flex", alignItems: "flex-end", gap: 6, height: 140, padding: "0 4px" }}>
        {data.map((d, i) => {
          const h = ((d.price - min) / range) * 80 + 20;
          const isLast = i === data.length - 1;
          return (
            <div key={i} style={{ flex: 1, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
              <span style={{ fontSize: 10, fontWeight: isLast ? 800 : 500, color: isLast ? "#c0903a" : "#b8b0a8" }}>{d.price}</span>
              <div style={{
                width: "100%", height: `${h}%`, borderRadius: "6px 6px 0 0",
                background: isLast ? "linear-gradient(to top, #c0903a, #e2c87a)" : "#e8e0d4",
                transition: "height 0.5s cubic-bezier(0.4,0,0.2,1)",
                transitionDelay: `${i * 50}ms`,
              }} />
            </div>
          );
        })}
      </div>
      <div style={{ display: "flex", gap: 6, padding: "8px 4px 0" }}>
        {data.map((d, i) => (
          <div key={i} style={{ flex: 1, textAlign: "center", fontSize: 9, color: "#c8c0b8" }}>{d.period.replace("20","").replace(" ","")}</div>
        ))}
      </div>
    </div>
  );
}

